"use strict";var _blockSerializer = require("@/lib/editor/blockSerializer");


/**
 * Round-trip check for the editor's serializer, run in Node.
 *
 * Every kind the store can hold goes in as a block, comes back out of the
 * document model, and has to be the same record. This is the promise the
 * milestone is built on, so it is tested rather than asserted.
 */

const blocks = [
{ kind: 'text', text: 'Plain paragraph with no markup.' },
{ kind: 'text', text: 'A paragraph\nwith a line break\ninside it.' },
{ kind: 'markdown', source: '**bold words** written as `source`, kept as source.' },
{ kind: 'markdown', source: '- a list that was never parsed\n- second item' },
{
  kind: 'rich',
  runs: [
  { text: 'Ordinary words, then ' },
  { text: 'bold', bold: true },
  { text: ', ' },
  { text: 'italic', italic: true },
  { text: ', ' },
  { text: 'npm run build', code: true },
  { text: ' and a ' },
  { text: 'link', href: 'https://example.com/docs' },
  { text: '.' }]

},
{
  kind: 'rich',
  runs: [
  { text: 'first line' },
  { text: '\n' },
  { text: 'second line' },
  { text: ' with ', bold: true },
  { text: 'a break on a marked run', bold: true },
  { text: '\n', bold: true },
  { text: 'third line' }]

},
{ kind: 'heading', level: 1, text: 'Title heading' },
{ kind: 'heading', level: 2, text: 'A heading with a\nnewline in it' },
{ kind: 'heading', level: 3, text: 'H3' },
{ kind: 'heading', level: 4, text: 'H4' },
{ kind: 'heading', level: 5, text: 'H5' },
{ kind: 'heading', level: 6, text: 'H6' },
{ kind: 'list', ordered: false, items: ['one', 'two', 'three with a\nsecond line'] },
{ kind: 'list', ordered: true, items: ['first', 'second'] },
{ kind: 'blockquote', text: 'A quote\nover two lines' },
{
  kind: 'code',
  code: 'const a = 1\nconsole.log(a)',
  language: 'typescript',
  filename: 'app.ts',
  caption: 'the caption that came from the export'
},
{ kind: 'code', code: 'SELECT 1;', language: 'sql' },
{ kind: 'code', code: 'no language at all' },
{
  kind: 'table',
  headers: ['Model', 'Turns', 'Notes'],
  rows: [
  ['GPT', '12', 'a cell with a\nsecond line'],
  ['Claude', '3', '']],

  caption: 'Usage by model'
},
{ kind: 'table', headers: ['A', 'B'], rows: [['1', '2']] },
{ kind: 'math', expression: '\\int_0^1 x^2\\,dx = \\tfrac{1}{3}', display: true },
{ kind: 'math', expression: 'E = mc^2', display: false },
{ kind: 'link', href: 'https://example.com/a?b=1&c=2', label: 'the docs' },
{ kind: 'link', href: 'mailto:someone@example.com', label: 'write to us' },
{ kind: 'link', href: 'javascript:alert(1)', label: 'a dangerous address' },
{
  kind: 'image',
  src: 'data:image/png;base64,iVBORw0KGgo=',
  alt: 'A chart of turns per model'
},
{ kind: 'image', alt: 'A picture the export only referenced', pending: true },
{
  kind: 'file',
  name: 'appendix.pdf',
  mimeType: 'application/pdf',
  sizeBytes: 245760,
  note: 'The export referenced this file but did not include its bytes.'
},
{ kind: 'file', name: 'canvas.txt' },
{ kind: 'unsupported', reason: 'A whiteboard canvas PromptPaper cannot represent', elementType: 'canvas' },
{ kind: 'unsupported', reason: 'Something else' }];


/** `undefined` fields and absent fields are the same record to the store. */
const shape = (value) => JSON.parse(JSON.stringify(value ?? null));

const read = (0, _blockSerializer.docToBlocks)((0, _blockSerializer.blocksToDoc)(blocks));
const expected = shape(blocks);
const actual = shape(read);

const failures = [];
blocks.forEach((block, index) => {
  const before = JSON.stringify(expected[index]);
  const after = JSON.stringify(actual[index] ?? null);
  if (before !== after) failures.push(`block ${index + 1} (${block.kind})\n  in:  ${before}\n  out: ${after}`);
});

if (expected.length !== actual.length)
failures.push(`count: ${expected.length} in, ${actual.length} out`);

console.log(failures.length === 0 ? 'ROUND-TRIP OK' : `ROUND-TRIP FAILED (${failures.length})`);
for (const failure of failures) console.log(failure);

// A paragraph nobody reformatted must not turn into a `rich` block.
const kinds = read.map((block) => block.kind);
console.log('kinds out:', kinds.join(', ')); /* v9-5bfadec6f9ca66dd */
